import{_ as t,o as i,c as n,aa as a}from"./chunks/framework.BAs_AphD.js";const o="/buildary-help-preview/media/en/diary/en_m_podepis.png",u=JSON.parse('{"title":"Signing in the Mobile App","description":"","frontmatter":{"title":"Signing in the Mobile App","wiki":"en:diary:m_signing"},"headers":[],"relativePath":"en/diary/m_signing.md","filePath":"en/diary/m_signing.md","lastUpdated":1794388980000}'),r={name:"en/diary/m_signing.md"};function s(l,e,g,c,h,d){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="signing-in-the-mobile-app" tabindex="-1">Signing in the Mobile App <a class="header-anchor" href="#signing-in-the-mobile-app" aria-label="Permalink to &quot;Signing in the Mobile App&quot;">​</a></h1><p>Buildary has 2 levels of signing:</p><ul><li>In the <strong>Other entries</strong> section, where each record author should sign their own record. The option to sign a record is available in the context menu of each additional record, and only the author of the record can sign it.</li><li><strong>Daily Report</strong>, where signing locks the entire day. All Other entries for the given day must be signed before the Daily Report can be signed. The option to sign the day is available in the day&#39;s context menu.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The signing method is configured in the user account. If you have configured your signing method through the web application, the same settings remain valid when logging in to the same account through the mobile app. Likewise, if you change the signing settings in the mobile app, the change will also be reflected in the web interface.</p></div><h2 id="signature-settings" tabindex="-1">Signature Settings <a class="header-anchor" href="#signature-settings" aria-label="Permalink to &quot;Signature Settings&quot;">​</a></h2><figure class="shot" style="--w:350px;"><img src="'+o+'" alt="" width="300" loading="lazy"></figure><p>If the settings were configured through the web interface, those settings, including the signature appearance, also apply to the mobile app. By default, signing via an external application is selected.</p><p><strong>To change the signing settings, go to Menu → Settings → Signature Settings in the app.</strong></p><p>The window offers <strong><strong>4 possible signing methods</strong></strong>:</p><ul><li><strong>Buildary Certificate</strong> - a NON-QUALIFIED certificate will be used. You need to select the signature appearance below.</li><li><strong>Qualified Certificate</strong> - the selected certificate issued by a certification authority and exported to the mobile device will be used. When selecting the certificate, you need to locate the PFX file in the device storage. After entering the correct password, the certificate will be uploaded to Buildary. You need to select the signature appearance below.</li><li><strong>I.CA Service</strong> - available only to holders of a qualified certificate issued by I.CA on a secure device who have activated this service with I.CA. You need to select the signature appearance below.</li><li><strong>Sign in an External Application</strong> - Buildary generates a document in PDF format, which the user opens in an external application that allows them to sign it, and then uploads it back to Buildary. The signature appearance is not configured here. Its appearance is created by the external signing application.</li></ul><p><strong><strong>Signature Appearance</strong></strong> - must be configured for the first 3 signing methods. There are 3 options:</p><ul><li><em><strong>Image + Text</strong></em> - the graphical signature will contain an image (a selected file or a graphical signature created using the &quot;Draw&quot; option) and a text component, which the application automatically adds using the current data: the user&#39;s name (according to the currently logged-in user) and their role in the Project Diary being signed.</li><li><em><strong>Image</strong></em> - the graphical signature will contain only an image, either a selected file or a graphical signature created using the &quot;Draw&quot; option.</li><li><em><strong>Text</strong></em> - the graphical signature will contain only a text component, which the application automatically adds using the current data: the user&#39;s name (according to the currently logged-in user) and their role in the Project Diary being signed.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the signing settings have been changed, you need to reload the diary for the changes to take effect.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you have a certificate stored on your computer and need to transfer it to your mobile device, see the procedure described in the <a href="/buildary-help-preview/en/diary/m_certificate">separate help chapter</a>.</p></div>',14)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
